"use client";

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '@/lib/supabase';
import { 
  Layers, 
  Plus, 
  Trash2,
  FolderTree,
  Image as ImageIcon,
  Loader2,
  CheckCircle2,
  ToggleLeft,
  ToggleRight
} from 'lucide-react';

// Client-Side Canvas WebP Image Compressor
const compressAndConvertToWebP = (file: File, maxWidth = 800, quality = 0.82): Promise<File> => {
  return new Promise((resolve) => {
    if (!file.type.startsWith('image/')) {
      return resolve(file);
    }

    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;

        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }

        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);

        canvas.toBlob(
          (blob) => {
            if (blob) {
              const cleanName = file.name.substring(0, file.name.lastIndexOf('.')) || 'category';
              const webpFileName = `${cleanName}_${Date.now()}.webp`;
              const webpFile = new File([blob], webpFileName, { type: "image/webp" });
              resolve(webpFile);
            } else {
              resolve(file);
            }
          },
          "image/webp",
          quality
        );
      };
      img.onerror = () => resolve(file);
    };
    reader.onerror = () => resolve(file);
  });
};

export default function CategoryManager() {
  const [categories, setCategories] = useState<any[]>([]);
  
  const [newCat, setNewCat] = useState("");
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [compressing, setCompressing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchCategories = async () => {
    const { data } = await supabase.from('categories').select('*').order('name');
    if (data) setCategories(data);
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setCompressing(true);
    try {
      const webpFile = await compressAndConvertToWebP(file);
      setImageFile(webpFile);
    } catch (err) {
      console.error('Image compression error:', err);
      setImageFile(file);
    } finally {
      setCompressing(false);
    }
  };

  const handleAddCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCat.trim()) return alert("Please enter a category name.");

    // MANDATORY IMAGE UPLOAD GUARD
    if (!imageFile) {
      return alert("Please upload a category photo before saving.");
    }

    setIsUploading(true);

    try {
        let imageUrl = "";

        const fileName = `${Date.now()}_${Math.random().toString(36).substring(2)}.webp`;
        const { error: uploadError } = await supabase.storage
          .from('categories')
          .upload(fileName, imageFile, { contentType: 'image/webp' });

        if (uploadError) throw uploadError;

        const { data: urlData } = supabase.storage
          .from('categories')
          .getPublicUrl(fileName);

        imageUrl = urlData.publicUrl;

        const { error } = await supabase.from('categories').insert({
          name: newCat.trim(),
          image_url: imageUrl,
          status: 'active',
        });

        if (error) throw error;

        setNewCat("");
        setImageFile(null);
        if (fileInputRef.current) fileInputRef.current.value = "";
        fetchCategories();
    } catch (error: any) {
        console.error("Error adding category:", error);
        alert("Failed to add category: " + (error.message || "Upload failed"));
    } finally {
        setIsUploading(false);
    }
  };

  const handleToggleCategoryStatus = async (catId: string, currentStatus: string) => {
    const newStatus = currentStatus === 'active' ? 'inactive' : 'active';
    try {
      const { error } = await supabase
        .from('categories')
        .update({ status: newStatus })
        .eq('id', catId);

      if (!error) {
        fetchCategories();
      } else {
        alert('Failed to update status: ' + error.message);
      }
    } catch (err) {
      console.error('Error toggling category status:', err);
    }
  };

  const handleDeleteCategory = async (catId: string) => {
    if(!confirm("Are you sure? This will delete the category.")) return;

    try {
      const { error } = await supabase.from('categories').delete().eq('id', catId);
      if (!error) fetchCategories();
    } catch (error) {
      console.error("Error deleting category:", error);
      alert("Failed to delete category");
    }
  };

  const triggerFileSelect = () => fileInputRef.current?.click();

  return (
    <div className="space-y-6">
      
      {/* HEADER */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl font-semibold text-[#1a1a1a]">Category Management</h1>
          <p className="text-[13px] text-[#616161] mt-0.5">Manage storefront categories and toggle visibility.</p>
        </div>
      </div>

      {/* ADD CATEGORY FORM */}
      <div className="bg-white p-4 rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] max-w-3xl">
        <form onSubmit={handleAddCategory} className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
          
          <input
            required
            value={newCat}
            onChange={(e) => setNewCat(e.target.value)}
            placeholder="Category name (e.g. Fresh Fish & Seafood)..."
            className="flex-1 bg-[#f7f7f7] border border-gray-200 rounded-lg px-3 h-9 text-[13px] text-[#303030] outline-none"
          />

          <div className="flex items-center gap-2 w-full sm:w-auto">
             <input 
                type="file" 
                ref={fileInputRef}
                onChange={handleImageSelect}
                className="hidden"
                accept="image/*"
             />
             
             {compressing ? (
                <button type="button" disabled className="h-9 px-3 bg-gray-100 text-gray-400 rounded-lg text-xs font-medium flex items-center gap-1.5">
                  <Loader2 size={14} className="animate-spin text-gray-500" /> WebP...
                </button>
             ) : imageFile ? (
                <button 
                    type="button" 
                    onClick={triggerFileSelect}
                    className="flex-1 sm:flex-none flex items-center gap-2 bg-[#cdfed4] text-[#014b40] h-9 px-3 rounded-lg text-xs font-medium transition-colors"
                >
                    <CheckCircle2 size={14} />
                    <span className="truncate max-w-[100px]">{imageFile.name}</span>
                </button>
             ) : (
                <button 
                    type="button" 
                    onClick={triggerFileSelect}
                    className="flex-1 sm:flex-none flex items-center justify-center gap-2 h-9 px-3.5 bg-[#f7f7f7] hover:bg-gray-100 border border-gray-200 rounded-lg text-xs font-medium text-[#303030] transition-colors whitespace-nowrap"
                >
                    <ImageIcon size={15} />
                    <span>Upload image *</span>
                </button>
             )}

            <button
                type="submit" 
                disabled={!newCat.trim() || !imageFile || isUploading || compressing}
                className="flex-1 sm:flex-none bg-[#303030] hover:bg-[#1a1a1a] text-white h-9 px-4 rounded-lg text-[13px] font-medium disabled:opacity-50 transition-colors flex items-center justify-center gap-1.5"
            >
                {isUploading ? (
                    <Loader2 size={15} className="animate-spin" />
                ) : (
                    <>
                        <Plus size={15} />
                        Add category
                    </>
                )}
            </button>
          </div>
        </form>
      </div>

      {/* CATEGORY CARDS GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {categories.map((cat) => {
          const isActive = (cat.status || 'active') === 'active';

          return (
            <div key={cat.id} className="bg-white rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] p-4 flex justify-between items-center">

              <div className="flex gap-3 items-center">
                <div className="h-12 w-12 rounded-lg bg-[#f7f7f7] border border-gray-200 flex-shrink-0 overflow-hidden">
                    {cat.image_url ? (
                        <img src={cat.image_url} alt={cat.name} className="h-full w-full object-cover" />
                    ) : (
                        <div className="h-full w-full flex items-center justify-center text-gray-300">
                            <ImageIcon size={18} />
                        </div>
                    )}
                </div>

                <div>
                  <h3 className="text-[13px] font-semibold text-[#1a1a1a]">{cat.name}</h3>
                  <span className={`inline-flex items-center px-2 h-5 rounded-full text-[11px] font-medium mt-1 ${
                    isActive ? 'bg-[#cdfed4] text-[#014b40]' : 'bg-[#e3e3e3] text-[#303030]'
                  }`}>
                    {isActive ? 'Active on storefront' : 'Hidden from storefront'}
                  </span>
                </div>
              </div>

              <div className="flex items-center gap-2">
                <button
                  onClick={() => handleToggleCategoryStatus(cat.id, cat.status || 'active')}
                  className={`h-8 px-2.5 rounded-lg text-xs font-medium border transition-colors flex items-center gap-1.5 ${
                    isActive ? 'bg-[#cdfed4] text-[#014b40] border-emerald-200' : 'bg-[#e3e3e3] text-[#303030] border-gray-200'
                  }`}
                  title={isActive ? "Disable category" : "Enable category"}
                >
                  {isActive ? <ToggleRight size={16} /> : <ToggleLeft size={16} />}
                  <span>{isActive ? 'Active' : 'Disabled'}</span>
                </button>

                <button
                  onClick={() => handleDeleteCategory(cat.id)}
                  className="p-1.5 text-gray-400 hover:text-red-600 rounded-lg hover:bg-rose-50 transition-colors"
                  title="Delete category"
                >
                  <Trash2 size={16} />
                </button>
              </div>

            </div>
          );
        })}
      </div>

    </div>
  );
}
